async function editMessage(id,messages){const m=messages.find(x=>String(x.id)===String(id));if(!m||m.senderId!==visitorId)return;const text=prompt('Edit your message:',m.text);if(text===null)return;if(!text.trim()||text.length>255){alert('Message must be 1–255 characters.');return}try{await api(`rooms/${activeRoom.id}/messages/${id}`,{method:'PATCH',body:JSON.stringify({text:text.trim()})});syncRoom()}catch(e){alert(errorText(e))}}
const reactionToggles=new Map();
function updateReactionCount(id,emoji,delta){const wrap=document.querySelector(`[data-message-reactions="${CSS.escape(String(id))}"]`);if(!wrap)return;let chip=[...wrap.querySelectorAll('.reaction-count')].find(b=>b.dataset.emoji===emoji);let count=chip?Number(chip.dataset.count||chip.textContent.trim().slice(emoji.length).trim()||0):0;count=Math.max(0,count+delta);if(count===0){chip?.remove();return}if(!chip){chip=document.createElement('button');chip.className='tool reaction-count';chip.dataset.react=id;chip.dataset.emoji=emoji;chip.setAttribute('aria-label',`${emoji} ${count} reactions`);wrap.querySelector('.reaction-counts')?.append(chip);chip.onclick=()=>reactToMessage(id,emoji)}chip.dataset.count=String(count);chip.textContent=`${emoji} ${count}`;chip.setAttribute('aria-label',`${emoji} ${count} reactions`)}
async function reactToMessage(id,emoji){const key=`${id}:${emoji}`,wasActive=reactionToggles.get(key)===true;reactionToggles.set(key,!wasActive);updateReactionCount(id,emoji,wasActive?-1:1);try{await api(`rooms/${activeRoom.id}/messages/${id}/reactions`,{method:'POST',body:JSON.stringify({emoji})});syncRoom()}catch(e){reactionToggles.set(key,wasActive);updateReactionCount(id,emoji,wasActive?1:-1);alert(errorText(e))}}
async function updateTyping(typing){if(!activeRoom)return;try{const r=await api(`rooms/${activeRoom.id}/typing`,{method:'POST',body:JSON.stringify({typing})});const el=$('typing-indicator');if(el)el.textContent=(r.typing||[]).join(', ')+(r.typing?.length?' typing…':'')}catch{}}

function renderMembers(members){const onlineCount=members.filter(m=>Date.now()-m.lastSeen<30000).length;$('member-count').textContent=`(${onlineCount} online / ${members.length})`;$('member-list').innerHTML=members.map(m=>{const online=Date.now()-m.lastSeen<30000,controls=activeMember.role==='admin'&&m.visitorId!==visitorId?`<span class=\"member-controls\"><button class=\"tool\" data-mute=\"${esc(m.visitorId)}\" data-muted=\"${m.muted?'1':'0'}\">${m.muted?'Unmute':'Mute'}</button><button class=\"tool\" data-block=\"${esc(m.visitorId)}\">Block</button>${m.isCreator?'':`<button class=\"tool\" data-admin-role=\"${esc(m.visitorId)}\" data-promote=\"${m.role==='admin'?'0':'1'}\">${m.role==='admin'?'Demote':'Promote'}</button>`}</span>`:'';return `<div class=\"member\"><span>${esc(m.displayName)}${m.role==='admin'?' &middot; ADMIN':''}${m.muted?' &middot; MUTED':''}</span><span class=\"${online?'online-dot':''}\">${online?'&#9679; here':'away'}</span>${controls}</div>`}).join('');document.querySelectorAll('[data-block]').forEach(b=>b.onclick=()=>blockUser(b.dataset.block));document.querySelectorAll('[data-mute]').forEach(b=>b.onclick=()=>muteUser(b.dataset.mute,b.dataset.muted==='1'));document.querySelectorAll('[data-admin-role]').forEach(b=>b.onclick=()=>changeAdminRole(b.dataset.adminRole,b.dataset.promote==='1'));const sel=$('promote-member');if(sel)sel.innerHTML='<option value=\"\">Choose yourself or a member</option>'+members.map(m=>`<option value=\"${esc(m.visitorId)}\">${esc(m.displayName)}${m.role==='admin'?' (admin password reset)':''}</option>`).join('');const self=members.find(m=>m.visitorId===visitorId),muted=!!self?.muted;$('muted-notice').hidden=!muted;$('message-input').disabled=muted;$('send-message').disabled=muted;$('gif-button').disabled=muted;$('emoji-toggle').disabled=muted}
async function muteUser(targetId,muted){try{await api(`rooms/${activeRoom.id}/${muted?'unmute':'mute'}`,{method:'POST',body:JSON.stringify({targetId})});syncRoom()}catch(e){alert(errorText(e))}}
function renderActivity(items){const log=$('activity-log');if(log)log.innerHTML=items.map(a=>`<div class="activity-item"><time>${esc(formatDate(a.createdAt))}</time><span>${esc(a.text)}</span></div>`).join('')||'<div class="activity-empty">No activity yet.</div>'}
function renderSettings(){const admin=activeMember.role==='admin';$('settings-area').innerHTML=admin?`<details><summary>Room settings</summary><label class="label">ROOM NAME</label><input class="input" id="setting-name" maxlength="48"><label class="label">DESCRIPTION</label><textarea class="textarea" id="setting-description" maxlength="180"></textarea><label class="label">ROOM RULES</label><textarea class="textarea" id="setting-rules" maxlength="500"></textarea><label class="label">SELF-DESTRUCT AFTER (MINUTES, MAX 43,200)</label><input class="input" id="setting-expiry" type="number" min="1" max="43200"><button class="btn small full" id="save-settings">Save room settings</button><label class="label">MEMBER PASSWORD (BLANK REMOVES IT)</label><input class="input" id="setting-password" type="password" placeholder="New member password, or blank for none"><button class="btn secondary small full" id="save-password">Set / remove member password</button><label class="label">CREATE OR RESET AN ADMIN PASSWORD</label><select class="input" id="promote-member"><option value="">Choose yourself or a member</option></select><small class="field-hint">Generate an 8-character password for admin controls.</small><button class="btn secondary small full" id="promote-button">Generate admin password</button>${activeMember.isCreator||activeMember.isMaster?'<button class="btn danger small full" id="delete-room">Delete this room permanently</button>':''}<div class="note" id="settings-note"></div><details><summary>Admin activity log</summary><div class="activity" id="activity-log">Loading…</div></details></details>`:'<p>You are a guest in this room. Room settings are managed by the host.</p>';if(!admin)return;$('setting-name').value=activeRoom.name;$('setting-description').value=activeRoom.description||'';$('setting-rules').value=activeRoom.rules||'';$('setting-expiry').value=Math.max(1,Math.ceil((new Date(activeRoom.expiresAt)-Date.now())/60000));$('save-settings').onclick=saveSettings;$('save-password').onclick=savePassword;$('promote-button').onclick=promoteAdmin;if($('delete-room'))$('delete-room').onclick=deleteRoom}
async function deleteRoom(){if(!confirm('Delete this room and all its messages permanently? This cannot be undone.'))return;try{await api(`rooms/${activeRoom.id}`,{method:'DELETE'});cleanSubs();activeRoom=null;activeMember=null;seenMessageIds=null;history.replaceState({},'',location.pathname);showView('home');await refreshRooms()}catch(e){alert(errorText(e))}}
async function saveSettings(){const minutes=Number($('setting-expiry').value);if(!Number.isInteger(minutes)||minutes<1||minutes>43200){note('settings-note','Expiry must be 1 to 43,200 minutes.','error');return}try{const r=await api(`rooms/${activeRoom.id}/settings`,{method:'PATCH',body:JSON.stringify({name:$('setting-name').value.trim(),description:$('setting-description').value.trim(),rules:$('setting-rules').value.trim(),expiresMinutes:minutes})});updateRoom(r.room);note('settings-note','Settings saved.','success')}catch(e){note('settings-note',errorText(e),'error')}}
async function savePassword(){try{await api(`rooms/${activeRoom.id}/password`,{method:'PUT',body:JSON.stringify({password:$('setting-password').value})});$('setting-password').value='';note('settings-note','Password updated.','success')}catch(e){note('settings-note',errorText(e),'error')}}
async function promoteAdmin(){const targetId=$('promote-member').value;if(!targetId)return note('settings-note','Choose yourself or a room member first.','error');try{const r=await api(`rooms/${activeRoom.id}/admins`,{method:'POST',body:JSON.stringify({targetId})}),isSelf=targetId===visitorId;if(isSelf)localStorage.setItem(`gather-admin-${activeRoom.id}`,r.adminKey);showAdminPassword(isSelf?'Your admin password':`Admin password for ${r.displayName}`,r.adminKey,isSelf?'Your admin password was reset. Save this new code.':'Share this code privately with the selected member.');note('settings-note',isSelf?'Your admin password was reset and saved in this browser.':'New admin password created. Share it privately with that member.','success')}catch(e){note('settings-note',errorText(e),'error')}}
async function changeAdminRole(targetId,promote){try{if(promote){const r=await api(`rooms/${activeRoom.id}/admins`,{method:'POST',body:JSON.stringify({targetId})});showAdminPassword(`Admin password for ${r.displayName}`,r.adminKey,'Share this code privately with the selected member.')}else{if(!confirm('Remove this member\'s admin access?'))return;await api(`rooms/${activeRoom.id}/admins/${encodeURIComponent(targetId)}`,{method:'DELETE'})}syncRoom()}catch(e){alert(errorText(e))}}
async function blockUser(targetId){if(!confirm('Block this person from rejoining this room?'))return;try{await api(`rooms/${activeRoom.id}/block`,{method:'POST',body:JSON.stringify({targetId})});syncRoom()}catch(e){alert(errorText(e))}}
async function deleteMessage(messageId){if(!confirm('Delete this message for everyone?'))return;try{await api(`rooms/${activeRoom.id}/messages/${messageId}`,{method:'DELETE'});syncRoom()}catch(e){alert(errorText(e))}}
async function sendMessage(){const text=$('message-input').value.trim();if(!text)return;if(text.length>255)return;try{const result=await api(`rooms/${activeRoom.id}/messages`,{method:'POST',body:JSON.stringify({text,kind:'text',replyToId:replyToMessageId})}),status=$('mention-status');if(/(^|\s)@creator\b/i.test(text))status.textContent=result.creatorAlert==='sent'?'Creator alert sent to Telegram.':result.creatorAlert==='rate_limited'?'A creator alert was already sent for this room in the last 5 minutes.':result.creatorAlert==='not_configured'?'Message sent; add TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID in Cloudflare Pages settings, then redeploy.':String(result.creatorAlert||'').startsWith('failed:')?`Message sent, but Telegram rejected the alert: ${result.creatorAlert.slice(7)}. Check the bot token, chat ID, and that the bot has been started or added to that chat.`:'Message sent; Telegram could not deliver the alert.';else if(/(^|\s)@admin\b/i.test(text))status.textContent='Room admins have been alerted in chat.';else status.textContent='';$('message-input').value='';replyToMessageId=null;$('message-input').placeholder='Write a message… (255 characters)';$('reply-status').hidden=true;$('reply-cancel').hidden=true;updateTyping(false);updateCount();syncRoom()}catch(e){alert(errorText(e))}}
let mediaKind='gif';async function searchMedia(){const grid=$('media-results');grid.innerHTML='<div class="empty">Searching…</div>';try{const q=$('media-query').value.trim();if(q.length>50)throw new Error('Search terms can be up to 50 characters.');const {apiKey}=await api('media'),endpoint=q?'search':'trending',url=new URL(`https://api.giphy.com/v1/${mediaKind==='sticker'?'stickers':'gifs'}/${endpoint}`);url.searchParams.set('api_key',apiKey);url.searchParams.set('client_key','hushly_chat');url.searchParams.set('limit','24');url.searchParams.set('rating','pg-13');if(q)url.searchParams.set('q',q);const response=await fetch(url),payload=await response.json();if(!response.ok)throw new Error('GIPHY search failed. Check the key and its request limit.');const items=(payload.data||[]).map(x=>({id:x.id,title:x.title||'',url:x.images?.original?.url||x.images?.fixed_height?.url,preview:x.images?.fixed_width_small?.url||x.images?.fixed_height_small?.url})).filter(x=>x.url&&x.preview);grid.innerHTML=items.length?items.map(x=>`<button type="button" data-media="${esc(x.url)}" title="${esc(x.title)}"><img src="${esc(x.preview)}" alt="${esc(x.title||mediaKind)}" loading="lazy"></button>`).join(''):'<div class="empty">No results. Try another search.</div>';grid.querySelectorAll('[data-media]').forEach(b=>b.onclick=()=>postMedia(b.dataset.media))}catch(e){grid.innerHTML=`<div class="empty">${esc(errorText(e))}</div>`}}
async function sendGif(){ $('media-query').value='';$('media-modal').classList.add('show');await searchMedia() }
async function postMedia(url){try{await api(`rooms/${activeRoom.id}/messages`,{method:'POST',body:JSON.stringify({kind:'gif',gifUrl:url,text:''})});$('media-modal').classList.remove('show');syncRoom()}catch(e){alert(errorText(e))}}
function updateCount(){$('message-count').textContent=`${$('message-input').value.length} / 255`}
async function openMasterDashboard(key='',roomId=''){busy(true);try{const headers=key?{'X-Master-Code':key}:{};const data=await api('master',{headers});if(key)localStorage.setItem('gather-master-code',key);masterRoomCache=data.rooms||[];const s=data.stats||{};for(const [id,value] of [['master-stat-rooms',s.rooms],['master-stat-messages',s.messages],['master-stat-members',s.members],['master-stat-online',s.online]])$(id).textContent=Number(value||0).toLocaleString();showView('master');selectedMasterRoomId=null;selectedMasterData=null;renderMasterRoomList();$('master-room-detail').innerHTML='<div class="empty">Select a room to inspect its users, messages, settings, and activity.</div>';if(roomId&&masterRoomCache.some(r=>r.id===roomId))await loadMasterRoom(roomId)}finally{busy(false)}}
function renderMasterRoomList(){const query=($('master-room-search')?.value||'').trim().toLowerCase(),rooms=masterRoomCache.filter(r=>`${r.id} ${r.name} ${r.creatorName}`.toLowerCase().includes(query));$('master-room-list').innerHTML=rooms.length?rooms.map(r=>`<button type="button" class="master-room-option ${r.id===selectedMasterRoomId?'selected':''}" data-master-room="${esc(r.id)}"><strong>${esc(r.name)}</strong><span class="master-room-code">${esc(r.id)} · ${r.hasPassword?'🔒 password protected':'🔓 open'}</span><span>By ${esc(r.creatorName)} · ${Number(r.memberCount||0)} members · ${Number(r.messageCount||0)} messages</span><span>Expires ${esc(formatDate(r.expiresAt))}</span></button>`).join(''):'<div class="empty">No active rooms found.</div>';document.querySelectorAll('[data-master-room]').forEach(b=>b.onclick=()=>loadMasterRoom(b.dataset.masterRoom))}
async function refreshMasterDashboard(){try{const data=await api('master');masterRoomCache=data.rooms||[];const s=data.stats||{};for(const [id,value] of [['master-stat-rooms',s.rooms],['master-stat-messages',s.messages],['master-stat-members',s.members],['master-stat-online',s.online]])$(id).textContent=Number(value||0).toLocaleString();renderMasterRoomList();if(selectedMasterRoomId&&masterRoomCache.some(r=>r.id===selectedMasterRoomId))await loadMasterRoom(selectedMasterRoomId);else if(selectedMasterRoomId){selectedMasterRoomId=null;selectedMasterData=null;$('master-room-detail').innerHTML='<div class="empty">Room deleted or expired.</div>'}}catch(e){alert(errorText(e))}}
async function loadMasterRoom(id){try{const data=await api(`rooms/${id}`);if(!data.member?.isMaster)throw new Error('Master access required. Re-enter the master key from the home screen.');selectedMasterRoomId=id;selectedMasterData=data;renderMasterRoomList();renderMasterRoomDetail(data)}catch(e){$('master-room-detail').innerHTML=`<div class="empty">${esc(errorText(e))}</div>`}}
function renderMasterRoomDetail(data){const r=data.room,online=m=>Date.now()-m.lastSeen<30000,memberRows=(data.members||[]).filter(m=>!m.isMaster),messages=data.messages||[],logs=data.activity||[],blocked=data.blocked||[];$('master-room-detail').innerHTML=`<div class="master-detail-head"><div><span class="master-kicker">ROOM CONTROL</span><h2>${esc(r.name)} <small>${esc(r.id)}</small></h2><p>Created by ${esc(r.creatorName)} · ${esc(formatDate(r.createdAt))}</p></div><button class="btn danger small" id="master-delete-room">Delete room</button></div><div class="master-room-stats"><span>${memberRows.length} users</span><span>${memberRows.filter(online).length} online</span><span>${messages.filter(m=>m.kind!=='event').length} messages</span><span>${r.hasPassword?'🔒 Password protected':'🔓 Open access'}</span><span>Expires ${esc(formatDate(r.expiresAt))}</span></div><details class="master-section" open><summary>Room settings and access</summary><div class="master-form-grid"><label class="label">ROOM NAME<input class="input" id="master-name" maxlength="48" value="${esc(r.name)}"></label><label class="label">SELF-DESTRUCT IN MINUTES<input class="input" id="master-expiry" type="number" min="1" max="43200" value="${Math.max(1,Math.ceil((new Date(r.expiresAt)-Date.now())/60000))}"></label><label class="label">DESCRIPTION<textarea class="textarea" id="master-description" maxlength="180">${esc(r.description||'')}</textarea></label><label class="label">ROOM RULES<textarea class="textarea" id="master-rules" maxlength="500">${esc(r.rules||'')}</textarea></label></div><button class="btn small" id="master-save-settings">Save settings</button><div class="master-password-row"><div><strong>${r.hasPassword?'Password enabled':'No room password'}</strong><p>Saved passwords are hashed and cannot be viewed. Set a new one or leave blank to remove it.</p></div><input class="input" id="master-password" type="password" maxlength="64" placeholder="New password, blank removes"><button class="btn secondary small" id="master-save-password">Update password</button></div></details><details class="master-section" open><summary>Users and moderation (${memberRows.length})</summary><div class="master-list">${memberRows.length?memberRows.map(m=>`<div class="master-user"><div><strong>${esc(m.displayName)} ${m.role==='admin'?'<em>ADMIN</em>':''}</strong><small>${online(m)?'● Online':'Away'} · ${m.muted?'Muted':'Can chat'} · ID ${esc(m.visitorId)}</small></div><div class="master-actions"><button class="tool" data-master-mute="${esc(m.visitorId)}" data-muted="${m.muted?'1':'0'}">${m.muted?'Unmute':'Mute'}</button><button class="tool" data-master-block="${esc(m.visitorId)}">Block</button>${m.isCreator?'':`<button class="tool" data-master-role="${esc(m.visitorId)}" data-promote="${m.role==='admin'?'0':'1'}">${m.role==='admin'?'Demote':'Promote'}</button>`}</div></div>`).join(''):'<div class="empty">No current members.</div>'}</div></details><details class="master-section" open><summary>All messages (${messages.length})</summary><div class="master-messages">${messages.length?messages.map(m=>`<article class="master-message"><div><strong>${esc(m.displayName||'System')}${m.role==='admin'?' · ADMIN':''}</strong><time>${esc(formatDate(m.createdAt))}</time></div><p>${m.kind==='gif'?`<a href="${esc(m.gifUrl)}" target="_blank" rel="noopener">GIF / sticker</a>${m.text?` · ${esc(m.text)}`:''}`:esc(m.text)}</p>${m.kind!=='event'?`<button class="tool" data-master-delete-message="${esc(m.id)}">Delete</button>`:''}</article>`).join(''):'<div class="empty">No messages.</div>'}</div></details><details class="master-section"><summary>Activity log (${logs.length})</summary><div class="master-messages">${logs.length?logs.map(a=>`<div class="master-log"><time>${esc(formatDate(a.createdAt))}</time><span>${esc(a.text)}</span></div>`).join(''):'<div class="empty">No activity recorded.</div>'}</div></details><details class="master-section"><summary>Blocked users (${blocked.length})</summary><div class="master-list">${blocked.length?blocked.map(b=>`<div class="master-user"><div><strong>${esc(b.visitorId)}</strong><small>Blocked ${esc(formatDate(b.createdAt))}</small></div><button class="tool" data-master-unblock="${esc(b.visitorId)}">Unblock</button></div>`).join(''):'<div class="empty">No blocked users.</div>'}</div></details><div class="note" id="master-action-note"></div>`;
 $('master-delete-room').onclick=async()=>{if(!confirm(`Permanently delete ${r.name} and all its messages?`))return;try{await api(`rooms/${r.id}`,{method:'DELETE'});selectedMasterRoomId=null;selectedMasterData=null;$('master-room-detail').innerHTML='<div class="empty">Room deleted.</div>';await refreshMasterDashboard()}catch(e){alert(errorText(e))}};
 $('master-save-settings').onclick=async()=>{const mins=Number($('master-expiry').value);if(!Number.isInteger(mins)||mins<1||mins>43200)return note('master-action-note','Expiry must be 1–43,200 minutes.','error');try{await api(`rooms/${r.id}/settings`,{method:'PATCH',body:JSON.stringify({name:$('master-name').value.trim(),description:$('master-description').value.trim(),rules:$('master-rules').value.trim(),expiresMinutes:mins})});await refreshMasterDashboard()}catch(e){note('master-action-note',errorText(e),'error')}};
 $('master-save-password').onclick=async()=>{try{await api(`rooms/${r.id}/password`,{method:'PUT',body:JSON.stringify({password:$('master-password').value})});note('master-action-note','Room password updated.','success');await loadMasterRoom(r.id)}catch(e){note('master-action-note',errorText(e),'error')}};
 document.querySelectorAll('[data-master-mute]').forEach(b=>b.onclick=()=>masterAction(r.id,b.dataset.muted==='1'?'unmute':'mute',{targetId:b.dataset.masterMute}));document.querySelectorAll('[data-master-block]').forEach(b=>b.onclick=async()=>{if(confirm('Block this user from rejoining this room?'))await masterAction(r.id,'block',{targetId:b.dataset.masterBlock})});document.querySelectorAll('[data-master-role]').forEach(b=>b.onclick=async()=>{const targetId=b.dataset.masterRole;try{if(b.dataset.promote==='1'){const out=await api(`rooms/${r.id}/admins`,{method:'POST',body:JSON.stringify({targetId})});showAdminPassword(`Admin password for ${out.displayName}`,out.adminKey,'Share this code privately with the selected member.')}else if(confirm('Remove this member admin access?'))await api(`rooms/${r.id}/admins/${encodeURIComponent(targetId)}`,{method:'DELETE'});await loadMasterRoom(r.id)}catch(e){alert(errorText(e))}});document.querySelectorAll('[data-master-delete-message]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this message for everyone?'))await masterAction(r.id,`messages/${b.dataset.masterDeleteMessage}`,null,'DELETE')});document.querySelectorAll('[data-master-unblock]').forEach(b=>b.onclick=()=>masterAction(r.id,`blocked/${encodeURIComponent(b.dataset.masterUnblock)}`,null,'DELETE'))}
async function masterAction(id,action,body,method='POST'){try{await api(`rooms/${id}/${action}`,{method,body:body?JSON.stringify(body):undefined});await refreshMasterDashboard()}catch(e){alert(errorText(e))}}
function exitMasterDashboard(){localStorage.removeItem('gather-master-code');selectedMasterRoomId=null;selectedMasterData=null;showView('home');refreshRooms()}
